#!/usr/bin/env bash
# Question 10: Busiest Pods in ${Q10_NS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/top
mkdir -p /opt/course/top
chown -R ubuntu:ubuntu /opt/course
kubectl create namespace "${Q10_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q10_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q10_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
names=(cache-a cache-b ledger-sync report-gen indexer)
sizes=($(shuf -e 12 30 70 45 20))
for i in 0 1 2 3; do
  kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${names[$i]}"'","namespace":"'"${Q10_NS}"'","labels":{"app":"perf"}},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sh","-c","dd if=/dev/zero of=/cache/fill bs=1M count='"${sizes[$i]}"' 2>/dev/null; sleep infinity"],"resources":{"limits":{"memory":"200Mi","cpu":"100m"}},"volumeMounts":[{"name":"cache","mountPath":"/cache"}]}],"volumes":[{"name":"cache","emptyDir":{"medium":"Memory","sizeLimit":"150Mi"}}]}}' >/dev/null
done
kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${names[4]}"'","namespace":"'"${Q10_NS}"'","labels":{"app":"perf"}},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sh","-c","while true; do :; done"],"resources":{"limits":{"cpu":"800m","memory":"32Mi"}}}]}}' >/dev/null
kubectl -n "${Q10_NS}" wait --for=condition=Ready pod -l app=perf --timeout=180s >/dev/null
sleep 30
for _ in $(seq 1 60); do
  [[ "$(kubectl top pod -n "${Q10_NS}" --no-headers 2>/dev/null | wc -l)" -ge 5 ]] && break
  sleep 5
done
[[ "$(kubectl top pod -n "${Q10_NS}" --no-headers 2>/dev/null | wc -l)" -ge 5 ]] || { echo "no Pod metrics in ${Q10_NS}" >&2; exit 1; }
: "${Q10_NS}"
